function freshState(){return{v:5,records:{},errorQueue:[],lastMode:'ordered',lastQuestionId:null,testFeedback:false,testStats:{started:0,completed:0,correct:0,wrong:0}};}
function subjectMeta(id){for(var i=0;i<SUBJECTS.length;i++)if(SUBJECTS[i].id===id)return SUBJECTS[i];return null;}
