function normalizeState(x){if(!x)return freshState();if(x.v===4){x.v=5;x.testStats={started:0,completed:0,correct:0,wrong:0};}if(x.v!==5)return freshState();x.records=x.records||{};x.errorQueue=Array.isArray(x.errorQueue)?x.errorQueue.map(Number).filter(function(v){return isFinite(v);}):[];if(typeof x.testFeedback!=='boolean')x.testFeedback=false;var t=x.testStats||{};x.testStats={started:Math.max(0,Number(t.started)||0),completed:Math.max(0,Number(t.completed)||0),correct:Math.max(0,Number(t.correct)||0),wrong:Math.max(0,Number(t.wrong)||0)};if(x.lastMode!=='random'&&x.lastMode!=='errors')x.lastMode='ordered';x.lastQuestionId=x.lastQuestionId==null?null:Number(x.lastQuestionId);return x;}
