function activateSubject(id,initial){var meta=subjectMeta(id);if(!meta){DATA={questions:[]};Q=[];SEARCH=[];byId={};resetExplanations();state=freshState();return;}currentSubjectId=id;DATA=(CATALOG.by_id&&CATALOG.by_id[id])||{questions:[]};Q=DATA.questions||[];byId={};SEARCH=new Array(Q.length);for(var i=0;i<Q.length;i++){byId[Q[i].id]=Q[i];SEARCH[i]=searchableQuestionText(Q[i]);}resetExplanations(meta);state=loadState(id);pruneState();if(ui){ui.testSetup.feedback=state.testFeedback===true;if(!initial){ui.session=null;ui.test=null;ui.selected=[];ui.match={};ui.matchOpen=null;ui.revealed=false;ui.result=null;ui.bankQuery='';ui.bankScrollY=0;ui.bankLimit=BANK_PAGE;ui.questionReturn=null;ui.tabHistory=[];ui.testSetup.count=Math.min(50,Q.length)||Q.length;ui.testSetup.ticket='all';ui.tab='learn';}}}
// Progress survives APK updates, but a rebuilt bank can drop or renumber items.
