function stats(){var attempted=0,mastered=0,errors=state.errorQueue.length,tries=0,wrong=0;Object.keys(state.records).forEach(function(k){var r=state.records[k];attempted++;tries+=r.attempts||0;wrong+=r.wrong||0;if(r.mastered)mastered++;});return{attempted:attempted,mastered:mastered,errors:errors,tries:tries,wrong:wrong};}
function testStats(){var t=state.testStats||{started:0,completed:0,correct:0,wrong:0},total=(t.correct||0)+(t.wrong||0),correctPct=total?Math.round((t.correct||0)/total*100):0;return{started:t.started||0,completed:t.completed||0,correct:t.correct||0,wrong:t.wrong||0,total:total,correctPct:correctPct,wrongPct:total?100-correctPct:0};}
function recordTestAnswer(correct){var t=state.testStats||(state.testStats={started:0,completed:0,correct:0,wrong:0});if(correct)t.correct=(t.correct||0)+1;else t.wrong=(t.wrong||0)+1;saveState();}
function recordTestStarted(){var t=state.testStats||(state.testStats={started:0,completed:0,correct:0,wrong:0});t.started=(t.started||0)+1;saveState();}
function recordTestCompleted(){var t=state.testStats||(state.testStats={started:0,completed:0,correct:0,wrong:0});t.completed=(t.completed||0)+1;saveState();}
function pct(){return Q.length?Math.round(stats().mastered/Q.length*100):0;}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function norm(s){return String(s||'').trim().toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ');}
function sanitizeHex(v){var x=String(v||'').trim();if(/^#[0-9a-fA-F]{6}$/.test(x))return x.toLowerCase();if(/^#[0-9a-fA-F]{3}$/.test(x))return ('#'+x.charAt(1)+x.charAt(1)+x.charAt(2)+x.charAt(2)+x.charAt(3)+x.charAt(3)).toLowerCase();return null;}
function defaultPalette(name){if(name==='dark')return{accent:'#7aa2ff',bg:'#111318',surface:'#191d24',text:'#f3f4f6',line:'#3a414c',good:'#4cc38a',bad:'#ff7b72'};return{accent:'#2458b8',bg:'#f3f4f6',surface:'#ffffff',text:'#111318',line:'#d0d5dd',good:'#177a4d',bad:'#b42318'};}
